using System;
using ACadSharp;
using ACadSharp.Entities;
using ACadSharp.IO;
using ACadSharp.Tables;
using CSMath;

class Probe {
 static MText MakeMText(string value, XYZ insert) => new MText { Value=value, InsertPoint=insert, Height=1.0, RectangleWidth=4.0 };
 static void Main(string[] args) {
  var doc=new CadDocument(ACadVersion.AC1032);
  var block=new BlockRecord("ACadSharpPeer");
  var def=new AttributeDefinition { Tag="P4PEER", Prompt="prompt", Value="definition fallback", Height=1.0,
    InsertPoint=new XYZ(1,2,3), AlignmentPoint=new XYZ(11,12,13), AttributeType=AttributeType.ConstantMultiLine,
    MText=MakeMText("definition MTEXT",new XYZ(21,22,23)) };
  block.Entities.Add(def); doc.BlockRecords.Add(block);
  var insert=new Insert(block) { InsertPoint=XYZ.Zero };
  insert.Attributes.Clear(); // remove constructor-generated copies before first save
  var child=new AttributeEntity { Tag="P4PEER", Value="attribute fallback", Height=1.0,
    InsertPoint=new XYZ(4,5,6), AlignmentPoint=new XYZ(31,32,33), AttributeType=AttributeType.MultiLine,
    MText=MakeMText("attribute MTEXT",new XYZ(41,42,43)) };
  insert.Attributes.Add(child); doc.Entities.Add(insert);
  Console.WriteLine("INTENT DEF alignment=11,12,13 embedded=21,22,23; ATTRIB alignment=31,32,33 embedded=41,42,43");
  DxfWriter.Write(args[0],doc,false);
  Console.WriteLine("WRITTEN " + args[0]);
 }
}
